-- ----------------------------
-- Table structure for wf_serial_number
-- ----------------------------
DROP TABLE IF EXISTS `wf_serial_number`;
CREATE TABLE `wf_serial_number` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户 id',
  `serial_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '序列标识（formKey.fieldKey，防跨表单重号）',
  `period` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '重置周期键（day=yyyyMMdd/month=yyyyMM/year=yyyy/never=ALL）',
  `seq` bigint NOT NULL DEFAULT '0' COMMENT '当前流水号（upsert 自增）',
  `updated_at` datetime DEFAULT NULL COMMENT '最近取号时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_serial` (`tenant_id`,`serial_key`,`period`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自动编号流水号计数（Task 3-d）';

-- ----------------------------
-- Records of wf_serial_number
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for wf_task_comment
